var e={"where.project":`Project`,"where.topic":`Topic`,"where.projectHelp":`A project groups the topics of one subject. Its CLAUDE.md and memory apply to all its topics.`,"where.topicHelp":`The topic is this session's working folder: Harness works there with the topic's CLAUDE.md and memory, plus the project's and the global ones.`,"where.topicHelpAny":`A topic is a working folder inside a project: Harness works there with the topic's CLAUDE.md and memory, plus the project's and the global ones.`,"where.move":`Click to move this session to another topic.`,"where.howTo":`Every session lives in a topic of a project: start one with the + of a topic in the list; click a session's badges to move it.`};export{e as default};